request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
binary-018

Cluster Arity:
2

Cluster Members:
[
  {
    "name": "ESTABLISHES_CONFLICT_RESOLUTION_PRECEDENCE",
    "definition": "Given an observation showing that two versions of the same artifact conflict, the reasoning decides which version prevails and justifies that choice with a stated precedence rationale rather than an arbitrary pick.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node choosing the prevailing version and stating the precedence rationale."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation exhibiting the conflicting versions of the artifact."
      }
    ],
    "assertion_conditions": [
      "The observation presents two conflicting alternatives for the same artifact.",
      "The reasoning selects one alternative as the resulting outcome.",
      "The reasoning states a rationale for why that alternative supersedes the other, such as which change is newer or which reflects the current situation."
    ],
    "exclusion_conditions": [
      "The reasoning only describes the conflict without selecting a side.",
      "A side is selected without any stated justification, or purely by position or convenience.",
      "The observation does not actually show conflicting alternatives for the same artifact."
    ]
  },
  {
    "name": "ADOPTS_PREEXISTING_CONFIGURATION_AS_INTENDED",
    "definition": "The reasoning treats a pre-existing configuration, artifact, or layout revealed by an observation as the environment's intended or authoritative design, and revises the plan so that the agent's own work conforms to or preserves it instead of overriding or duplicating it.",
    "parameters": [
      {
        "name": "conforming_reasoning",
        "type": "reasoning",
        "description": "The reasoning that characterizes the discovered artifact as intended or authoritative and revises the plan accordingly."
      },
      {
        "name": "discovery_observation",
        "type": "observation",
        "description": "The observation revealing the pre-existing configuration, layout, or artifact."
      }
    ],
    "assertion_conditions": [
      "The observation reveals a pre-existing configuration or artifact containing substantive settings, structure, or layout information.",
      "The reasoning explicitly characterizes that artifact as intended, pre-prepared, or authoritative for the environment.",
      "The reasoning changes planned actions so that the agent's own work conforms to or preserves the discovered artifact rather than replacing or duplicating it."
    ],
    "exclusion_conditions": [
      "The reasoning merely notes the artifact's existence without revising the plan.",
      "The discovered artifact is treated as incidental, defective, or as something to be replaced or overridden.",
      "No plan revision toward conformance with or preservation of the discovered artifact is expressed."
    ]
  },
  {
    "name": "EVALUATES_COMPETING_IMPLEMENTATIONS",
    "definition": "The reasoning compares the content or behavior of two or more distinct candidate implementations, versions, or variants of an artifact, as exposed by observations, and reaches a comparative judgement about their relative correctness or suitability.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node contrasting the candidate implementations or versions."
      },
      {
        "name": "variant_observations",
        "type": "observation[]",
        "description": "The observations that collectively expose two or more distinct candidate implementations or versions of the artifact."
      }
    ],
    "assertion_conditions": [
      "The cited observations collectively expose at least two distinct implementations, versions, or variants of the same artifact or of artifacts serving the same role.",
      "The reasoning contrasts their structure, logic, or behavior using identifiable content of those observations.",
      "The reasoning reaches a comparative judgement about correctness or suitability, which may reject some or all of the variants rather than selecting one of them."
    ],
    "exclusion_conditions": [
      "Only one implementation or version is exposed, so no comparative evaluation is possible.",
      "The reasoning describes or summarizes the variants without making any comparative correctness or suitability judgement.",
      "The contrasted content is not drawn from the cited observations.",
      "The reasoning compares candidate approaches it has not yet realized as artifacts rather than existing implementations or versions."
    ]
  },
  {
    "name": "EXPLAINS_ARTIFACT_BEHAVIOR_FROM_SOURCE",
    "definition": "The reasoning explains how an artifact realizes its behavior—including differing behavior across execution contexts—by interpreting specific source constructs present in an observation of the artifact's content.",
    "parameters": [
      {
        "name": "explanation_reasoning",
        "type": "reasoning",
        "description": "The reasoning node interpreting source constructs to explain the artifact's behavior."
      },
      {
        "name": "source_observation",
        "type": "observation",
        "description": "The observation containing the artifact or source content being interpreted."
      }
    ],
    "assertion_conditions": [
      "The observation contains source or artifact content.",
      "The reasoning references at least one specific construct, block, directive, or code element in that content.",
      "The reasoning explains how that construct causes or enables the artifact's behavior, including, where relevant, its differing behavior across execution contexts."
    ],
    "exclusion_conditions": [
      "The reasoning only summarizes test results, restates content, or describes behavior without tying it to specific source constructs.",
      "The observation does not contain source or artifact content.",
      "The reasoning references no concrete source construct."
    ]
  }
]

Previously Generated Predicate Names:
["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION", "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE", "INTERPRETS_OBSERVED_CONTENT_AS_TYPED_OR_STRUCTURED_INFORMATION"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "DERIVES_GOVERNING_ARTIFACT_JUDGMENT_FROM_OBSERVED_CONTENT",
  "definition": "The reasoning interprets the substantive content of an existing artifact, configuration, or set of candidate versions exposed by one or more observations, identifies specific observed constructs, settings, structures, or alternatives, and derives an evidence-grounded judgment that governs how the artifact is understood or handled—such as explaining its behavior, determining precedence between conflicting versions, comparatively assessing candidate implementations, or treating a pre-existing configuration as intended or authoritative.",
  "parameters": [
    {
      "name": "judgment_reasoning",
      "type": "reasoning",
      "description": "The reasoning node that interprets the observed artifact content and states a supported conclusion, comparison, precedence decision, authoritative characterization, or behavioral explanation."
    },
    {
      "name": "artifact_observation",
      "type": "observation[]",
      "description": "The observation or set of observations exposing the artifact's source, configuration, layout, versions, or candidate implementations whose identifiable content grounds the judgment."
    }
  ],
  "assertion_conditions": [
    "The cited observation or observations expose substantive artifact, source, configuration, layout, version, or implementation content rather than only a summary or result.",
    "The reasoning references identifiable elements of the observed content, such as source constructs, settings, structures, conflicting alternatives, or distinct implementation variants.",
    "The reasoning derives an evidence-grounded judgment about the artifact that governs its interpretation or handling, including explaining behavior, selecting a prevailing version with rationale, adopting a pre-existing structure as intended or authoritative, or comparatively judging correctness or suitability.",
    "The derived judgment is supported by the cited observed content rather than being asserted arbitrarily or merely restating the observation."
  ],
  "exclusion_conditions": [
    "The reasoning merely notes, summarizes, or describes the observed artifact content without deriving any governing explanatory, comparative, precedence, or authoritative judgment.",
    "The judgment is asserted without grounding in identifiable content from the cited observation or observations.",
    "The observation or observations contain no substantive artifact, source, configuration, implementation, or version content to interpret.",
    "For a comparative or conflict case, the cited observations do not expose distinct alternatives or variants to be assessed or resolved."
  ]
}

